LAYER
    INCLUDE "config/database.map"
    DATA "geom from (select id, flow_level, geom from alerts.get_wrf_streamflow('%time%', NULLIF('%country%', ''))) as subq using unique id using srid=4326"
    MASK "gha_admin_extent_mask"
    INCLUDE "shared/common-layer-properties.map"
    INCLUDE "classifications/wrf-streamflow.classes.map"
    METADATA
        "wms_title" "WRF-Hydro Stream Flow"
        "wms_abstract" "Daily stream flow levels from WRF-Hydro model"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    NAME "wrf_streamflow"
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2025-10-01"
        "country" "^[A-Za-z ]+$"
        "default_country" ""
    END
END
